items.inputSchema:
{
  "type": "object",
  "properties": {
    "source": {
      "type": "string",
      "enum": [
        "current",
        "demo",
        "url",
        "html",
        "browser_mcp"
      ],
      "description": "Use current to read the mode selected in the MetaWebMCP interface."
    },
    "goal": {
      "type": "string",
      "description": "What agents should be able to accomplish on the target site."
    },
    "url": {
      "type": "string",
      "description": "Required for URL or Browser MCP analysis."
    },
    "html": {
      "type": "string",
      "description": "Required when source is html."
    }
  },
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "capability_ids": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "maxItems": 12,
      "description": "Capability IDs to expose. Omit to use the checked candidates."
    },
    "overrides": {
      "type": "array",
      "maxItems": 12,
      "description": "Reviewed tool metadata. A name and description are required for every selected capability from an external or supplied target.",
      "items": {
        "type": "object",
        "properties": {
          "capability_id": {
            "type": "string"
          },
          "name": {
            "type": "string"
          },
          "description": {
            "type": "string"
          },
          "risk": {
            "type": "string",
            "enum": [
              "read",
              "write",
              "consequential"
            ]
          }
        },
        "required": [
          "capability_id"
        ],
        "additionalProperties": false
      }
    }
  },
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "tool_names": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "maxItems": 25,
      "description": "Optional generated tool subset to test."
    }
  },
  "additionalProperties": false
}
